('NHOM-TIEN-CNC', 'Máy Tiện CNC Chính Xác', 0, 'Dòng máy tiện CNC gia công chi tiết cơ khí tròn xoay'), ('NHOM-PHAY-CNC', 'Trung Tâm Phay CNC 3-5 Trục', 0, 'Gia công bề mặt cong, khuôn mẫu và linh kiện phức tạp'), ('NHOM-MAY-EP', 'Máy Ép & Chấn Thủy Lực', 0, 'Hệ thống máy ép thủy lực và chấn định hình kim loại tấm'), ('NHOM-ROBOT-HAN', 'Robot Hàn Tự Động Công Nghiệp', 0, 'Hệ thống cánh tay robot hàn tích hợp nguồn hàn MIG/TIG'), ('NHOM-BANG-TAI', 'Hệ Thống Băng Tải Chuyền', 0, 'Băng tải con lăn, băng tải cao su trung chuyển phôi sản xuất'), ('NHOM-NEN-KHI', 'Hệ Thống Máy Nén Khí Trục Vít', 0, 'Trạm máy nén khí áp lực 7-10 bar cung cấp toàn xưởng'), ('NHOM-LO-HOI', 'Lò Hơi Công Nghiệp & Cấp Nhiệt', 0, 'Lò hơi tầng sôi và lò đốt dầu sinh nhiệt cho công nghệ sản xuất'), ('NHOM-HVAC', 'Hệ Thống Làm Mát Chiller & HVAC', 0, 'Cụm làm lạnh nước Chiller, tháp giải nhiệt và hệ thống AHU'), ('NHOM-CAT-LASER', 'Máy Cắt Laser Fiber Công Suất Lớn', 0, 'Thiết bị cắt tôn tấm chính xác bằng nguồn sợi quang laser'), ('CUM-SPINDLE', 'Cụm Trục Chính Spindle', 1, 'Cụm trục chính quay tốc độ cao máy tiện và phay CNC'), ('CUM-DAI-DAO', 'Cụm Đài Gá Dao Tự Động', 1, 'Cụm đài dao xoay servo 8-12 vị trí kèm chốt khóa thủy lực'), ('CUM-DAU-NEN', 'Cụm Đầu Nén Trục Vít Khí', 1, 'Cặp trục vít nén khí đực-cái và cụm vòng bi đỡ chặn'), ('CUM-XI-LANH', 'Cụm Xi Lanh & Piston Ép Thủy Lực', 1, 'Cán piston, buồng dầu áp lực cao và phớt gạt bụi máy ép');
