('LOI-QUA-NHIET', 'Quá nhiệt động cơ & trục chính', 'Nhiệt độ vỏ trục chính hoặc động cơ vượt ngưỡng 65 độ C, rơ le nhiệt nhảy'), ('LOI-RO-RI-DAU', 'Rò rỉ dầu thủy lực & bôi trơn', 'Áp suất tụt dưới mức cài đặt, có vết dầu loang trên sàn máy hoặc cụm van'), ('LOI-CHAY-MOTOR', 'Cháy cuộn dây động cơ điện', 'Mùi khét bốc ra từ stator, nhảy aptomat tổng, động cơ mất pha không quay'), ('LOI-CAM-BIEN-PLC', 'Hỏng cảm biến & tín hiệu PLC', 'Đèn báo cảm biến mất tín hiệu, máy dừng chu trình tự động báo lỗi I/O'), ('LOI-KET-DAO', 'Kẹt cơ cấu thay dao ATC / đài dao', 'Đài gá dao không xoay đổi vị trí, tay kẹp dao kẹt giữa hành trình'), ('LOI-RUNG-LAC', 'Rung lắc mâm cặp & cụm trục', 'Độ đảo trục vượt mức 0.02mm, phát tiếng kêu gằn lớn khi quay tốc độ cao'), ('LOI-DUT-DAY-DAI', 'Đứt hoặc chùng dây đai truyền động', 'Tốc độ trục không đồng bộ với động cơ, dây đai curoa nứt rách hoặc trượt'), ('LOI-AP-SUAT-KHI', 'Tụt áp suất khí nén cấp nguồn', 'Đồng hồ áp tụt dưới 5.0 bar, cơ cấu kẹp phôi và van xả khí không đóng mở'), ('LOI-NGHEN-LOC', 'Tắc nghẽn lõi lọc gió & lọc dầu', 'Chênh lệch áp suất qua phin lọc lớn hơn 1.2 bar, lưu lượng làm việc suy giảm'), ('LOI-BIEN-TAN', 'Lỗi khối điều khiển biến tần', 'Biến tần báo mã lỗi quá dòng OC hoặc quá áp OV trên màn hình hiển thị'), ('LOI-AP-SUAT-HOI', 'Áp suất hơi vượt giới hạn an toàn', 'Van an toàn xả hơi liên tục, đồng hồ áp lò hơi tiến sát vạch đỏ nguy hiểm'), ('LOI-RO-RI-NUOC', 'Rò rỉ nước tuần hoàn Chiller', 'Tụt áp đường ống nước lạnh, bơm tuần hoàn phát tiếng kêu do e khí');
